using System.Text.RegularExpressions;
using System.Text.Json.Nodes;
using System.Xml.Linq;
using Modeller.Core;
namespace Modeller.Application;
internal static class XmlTerminologyInspection
{
    private const string Oet="openEHR/v1/Template";
    private static readonly string[] Opt=["http://schemas.openehr.org/v1","http://schemas.openehr.org/v2"];
    internal static JsonObject Finding(string code,string location,string message,string severity="warning"){var finding=ModelChecks.Finding(severity,code,message);finding["location"]=location;finding["evidence"]=new JsonObject{["scope"]="explicit_xml_constraints_and_project_catalogue"};return finding;}
    private static IEnumerable<XElement> Children(XElement node)=>node.Elements().Where(child=>child.Name.Namespace==node.Name.Namespace);
    private static string? Type(XElement node){var value=(string?)node.Attribute(XName.Get("type","http://www.w3.org/2001/XMLSchema-instance"));if(value is null)return null;var parts=value.Split(':');if(parts.Length>2)return null;var ns=parts.Length==2?node.GetNamespaceOfPrefix(parts[0]):node.GetDefaultNamespace();return ns==node.Name.Namespace?parts[^1]:null;}
    private static JsonObject Context(XElement element){string? path=null;string? archetype=null;var placements=new List<JsonObject>();foreach(var node in element.AncestorsAndSelf()){if(node.Name.Namespace!=element.Name.Namespace)continue;path??=(string?)node.Attribute("path");var id=(string?)node.Attribute("archetype_id");if(string.IsNullOrEmpty(id)){var nested=Children(node).FirstOrDefault(c=>c.Name.LocalName=="archetype_id");id=nested is null?null:Children(nested).FirstOrDefault(c=>c.Name.LocalName=="value")?.Value;}if(!string.IsNullOrEmpty(id)){archetype??=id;placements.Add(new JsonObject{["archetype"]=id,["path"]=(string?)node.Attribute("path")});}}placements.Reverse();return new JsonObject{["path"]=path,["archetype"]=archetype,["placements"]=new JsonArray(placements.Select(p=>(JsonNode)p).ToArray())};}
    internal static JsonObject Inspect(string content,string format){
        var hash=Data.Hash(content);var slots=new JsonArray();var bindings=new JsonArray();var findings=new JsonArray();var result=new JsonObject{["status"]="PARTIAL",["scope"]="explicit_xml_terminology",["content_sha256"]=hash,["slots"]=slots,["existing_bindings"]=bindings,["findings"]=findings,["model_changed"]=false};
        if(!new[]{"oet","opt","xml"}.Contains(format)){result["status"]="NOT_EXECUTED";findings.Add(Finding("TERMINOLOGY_INSPECTOR_UNAVAILABLE","","Inspect this source with a qualified openEHR engine."));return result;}
        var xml=Imports.Xml(content);var root=xml.Root;var ns=root?.Name.NamespaceName;if(root?.Name.LocalName!="template"||ns!=Oet&&!Opt.Contains(ns??"")||format=="oet"&&ns!=Oet||format=="opt"&&!Opt.Contains(ns??""))throw new ProcessingException("UNSUPPORTED_TERMINOLOGY_XML_PROFILE");var codingCount=0;
        void Walk(XElement element,string location){if(element.Name.NamespaceName==ns){var type=Type(element);JsonObject? slot=null;
            if(ns==Oet&&(type=="textConstraint"||new[]{"nameConstraint","nullFlavourConstraint","nullFlavorConstraint","SubjectOfCare"}.Contains(element.Name.LocalName))){
                var codes=new JsonArray();var unresolved=new JsonArray();var references=new JsonArray();var included=new JsonArray();var excluded=new JsonArray();foreach(var child in Children(element)){
                    if(child.Name.LocalName=="termQueryId")references.Add(new JsonObject{["kind"]="oet_named_query",["terminology_id"]=(string?)child.Attribute("terminologyID")??"",["language"]=(string?)child.Attribute("terminologyLang")??"",["query_name"]=(string?)child.Attribute("queryName")??"",["canonical"]=null,["version"]=null});
                    if(child.Name.LocalName is "includedValues" or "excludedValues"){var raw=child.Value;if(child.Name.LocalName=="excludedValues"){excluded.Add(raw);continue;}included.Add(raw);var match=Regex.Match(raw,"\\A([^\\s]+)::([^\\s]+)\\z");if(raw.Split("::",StringSplitOptions.None).Length==2&&match.Success)codes.Add(new JsonObject{["terminology_id"]=match.Groups[1].Value,["code"]=match.Groups[2].Value,["version"]=null});else unresolved.Add(raw);}
                }if(codes.Count+references.Count+included.Count+excluded.Count>0)slot=new JsonObject{["codings"]=codes,["unresolved_literals"]=unresolved,["existing_references"]=references,["included_values"]=included,["excluded_values"]=excluded,["limit_to_list"]=(string?)element.Attribute("limitToList")};
            }else if(Opt.Contains(ns!)&&type is "C_CODE_PHRASE" or "C_CODE_REFERENCE"){
                var system=Children(element).Where(child=>child.Name.LocalName=="terminology_id").SelectMany(Children).LastOrDefault(value=>value.Name.LocalName=="value")?.Value;var codes=new JsonArray();var references=new JsonArray();foreach(var child in Children(element)){if(child.Name.LocalName=="code_list")codes.Add(new JsonObject{["terminology_id"]=system,["code"]=child.Value,["version"]=null});if(child.Name.LocalName=="referenceSetUri"){string? canonical=child.Value;try{TerminologyWorkspace.Canonical(canonical);}catch(ProcessingException){canonical=null;}references.Add(new JsonObject{["kind"]="value_set_reference",["raw"]=child.Value,["canonical"]=canonical,["version"]=null});}}
                slot=new JsonObject{["codings"]=codes,["unresolved_literals"]=new JsonArray(),["existing_references"]=references,["included_values"]=new JsonArray(),["excluded_values"]=new JsonArray(),["limit_to_list"]=null};
            }else if(Opt.Contains(ns!)&&type=="C_TERMINOLOGY_CODE")findings.Add(Finding("TERMINOLOGY_EXPRESSION_NOT_RESOLVED",location,"AOM 2 terminology expressions require the qualified engine."));
            if(slot is not null){codingCount+=slot["codings"]!.AsArray().Count+slot["unresolved_literals"]!.AsArray().Count;if(slot["codings"]!.AsArray().Count>100||slot["included_values"]!.AsArray().Count+slot["excluded_values"]!.AsArray().Count>200||codingCount>2000)throw new ProcessingException("TERMINOLOGY_INSPECTION_LIMIT_EXCEEDED");var context=Context(element);slot["location"]=location;slot["element"]=element.Name.LocalName;slot["declared_path"]=context["path"]?.DeepClone();slot["archetype"]=context["archetype"]?.DeepClone();slot["context"]=context["placements"]!.DeepClone();slot["source_format"]=ns==Oet?"oet":"opt";slot["native_semantics_verified"]=false;slots.Add(slot);}
            if(Opt.Contains(ns!)&&element.Name.LocalName is "term_bindings" or "constraint_bindings")bindings.Add(new JsonObject{["location"]=location,["kind"]=element.Name.LocalName,["terminology"]=(string?)element.Attribute("terminology")??"",["xml_sha256"]=Data.Hash(element.ToString(SaveOptions.DisableFormatting)),["context"]=Context(element)});
            if(slots.Count+bindings.Count+findings.Count>100)throw new ProcessingException("TERMINOLOGY_INSPECTION_LIMIT_EXCEEDED");
        }var index=0;foreach(var child in element.Elements())Walk(child,location+"/"+(++index));}
        Walk(root!,"/1");result["limitations"]=new JsonArray("Inherited constraints, ADL/AOM expressions and model conformance require the qualified engine.","Element-position locators are tied to the exact source hash; they are not semantic openEHR paths.");return result;
    }
}
